const cfg = ($input.first().json && $input.first().json.config) || {};
const profile = cfg.profile || {};
const mustHave = cfg.must_have || {};
const exclude = cfg.exclude || {};
const notify = cfg.notify || {};
const minScore = (notify.min_score !== undefined && notify.min_score !== null) ? notify.min_score : 75;

const skillsText = Array.isArray(profile.skills) ? profile.skills.join(', ') : '';
const projectsText = Array.isArray(profile.projects) ? profile.projects.join('; ') : '';

const SYSTEM_MESSAGE = `You are screening job postings for a specific candidate. Score how well each posting matches their profile and preferences.

CANDIDATE PROFILE:
${profile.summary || ''}

Skills: ${skillsText}
Notable projects: ${projectsText}
Graduating: ${profile.graduation_year || ''}

RESPOND WITH STRICT JSON ONLY, matching exactly this shape, no other text, no markdown fences:
{
  "match_score": <integer 0-100>,
  "should_apply": <boolean>,
  "reason": "<string, at most 300 characters>",
  "missing_skills": ["<string>", ... at most 5 items],
  "deadline": "<string, exactly as stated in the posting (e.g. 'Rolling', '2026-09-15'), or null if the posting does not state one>",
  "eligibility": "<string, exactly as stated in the posting (e.g. 'Final year students, CGPA 7.0+'), or null if the posting does not state one>",
  "ctc_or_stipend": "<string, exactly as stated in the posting (e.g. '\u20b950,000/month', '12-18 LPA'), or null if the posting does not state one>"
}

HARD REQUIREMENTS (read the posting text carefully -- these are not optional preferences):
- Employment type: the candidate wants full-time roles, OR internships that explicitly offer a path to full-time conversion (PPO / pre-placement offer / return offer / "potential for full-time" stated anywhere in the text). A posting that is a plain internship with no stated full-time/PPO/conversion path anywhere in the description should score low and should_apply must be false, even if skills otherwise match well.
- Compensation floor: full-time roles need a stated CTC of at least ${mustHave.min_ctc_lpa || 'N/A'} LPA (with at least ${mustHave.min_in_hand_lpa || 'N/A'} LPA in-hand/base), and internships need a stated stipend of at least â‚¹${mustHave.min_stipend_inr_per_month || 'N/A'}/month. Foreign-currency compensation is fine -- convert to an approximate INR equivalent (roughly â‚¹83/USD, â‚¹90/EUR, â‚¹105/GBP) when judging. If the posting explicitly states compensation below this floor, score low and should_apply must be false, with the reason naming the shortfall. If compensation is not stated at all, do NOT penalize for it -- judge on other fit criteria as usual, per the ambiguity rule below.
- Experience level: the candidate is a fresher -- no full-time work history, only short (2-month) internships. If the posting explicitly requires professional full-time experience (e.g. "1+ years", "2-3 years experience", "minimum 2 years in a similar role"), score low and should_apply must be false. Internship-only backgrounds satisfy any "0 years" / "fresher" / "entry-level" requirement. If no experience requirement is stated, do not penalize.
- Graduation batch: the candidate graduates in ${mustHave.graduation_batch || profile.graduation_year || 'N/A'}. If the posting explicitly restricts eligibility to graduation batches that exclude that year (e.g. "2025/2026 batch only"), score low and should_apply must be false. If no batch restriction is stated, do not penalize.

Scoring guidance:
- match_score reflects genuine fit: skills overlap, seniority match, domain relevance.
- should_apply is true only if match_score suggests a real, actionable opportunity.
- reason is a concise, specific justification a human could act on in five seconds.
- missing_skills lists skills the posting wants that the candidate's profile doesn't show; empty array if none.
- deadline, eligibility, and ctc_or_stipend are extracted, never inferred: use null unless the posting text explicitly states one. Do not guess a deadline from posted_date, do not infer eligibility from role seniority, and do not estimate a salary/stipend from role or company reputation.
- When genuinely uncertain, score toward inclusion rather than exclusion -- a missed good match is a worse outcome than an extra alert.`;

const roleExcludes = (exclude.role_keywords || []).map(s => s.toLowerCase());
const companyExcludes = (exclude.companies || []).map(s => s.toLowerCase());
const allowedLocations = (mustHave.locations || []).map(s => s.toLowerCase());
const remoteOk = mustHave.remote_ok !== false;

function evaluatePrefilter(posting) {
  const role = (posting.role || '').toLowerCase();
  const company = (posting.company || '').toLowerCase();
  const location = (posting.location || '').toLowerCase().trim();

  for (const kw of roleExcludes) {
    if (kw && role.includes(kw)) return { passed: false, reason: 'excluded role keyword: ' + kw };
  }
  for (const kw of companyExcludes) {
    if (kw && company.includes(kw)) return { passed: false, reason: 'excluded company: ' + kw };
  }
  if (location) {
    const isRemote = remoteOk && location.includes('remote');
    const isAllowedCity = allowedLocations.some(loc => location.includes(loc));
    const mentionsIndia = location.includes('india');
    if (!isRemote && !isAllowedCity && !mentionsIndia) {
      return { passed: false, reason: 'location outside allowed set: ' + posting.location };
    }
  }
  return { passed: true, reason: null };
}

const postings = $('When Executed by Another Workflow').all();
const results = [];
for (const item of postings) {
  const p = item.json;
  const verdict = evaluatePrefilter(p);
  const userMessage = `COMPANY: ${p.company}
ROLE: ${p.role}
LOCATION: ${p.location || 'Not specified'}
EMPLOYMENT TYPE: ${p.employment_type || 'Not specified'}

DESCRIPTION:
${p.description || ''}`;

  results.push({
    json: {
      posting_id: p.id,
      content_hash: p.content_hash,
      company: p.company,
      role: p.role,
      location: p.location || null,
      employment_type: p.employment_type || null,
      apply_url: p.apply_url,
      source: p.source,
      prefilter_passed: verdict.passed,
      prefilter_reason: verdict.reason,
      system_message: SYSTEM_MESSAGE,
      user_message: userMessage,
      notify_min_score: minScore,
      model: 'claude-haiku-4-5-20251001',
      prompt_version_input: SYSTEM_MESSAGE
    }
  });
}
return results;

function tryValidate(rawText) {
  let parsed;
  try {
    const cleaned = (rawText || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
    parsed = JSON.parse(cleaned);
  } catch (e) {
    return { ok: false, error: 'JSON parse error: ' + e.message };
  }
  const errors = [];
  if (!Number.isInteger(parsed.match_score) || parsed.match_score < 0 || parsed.match_score > 100) errors.push('match_score must be an integer 0-100');
  if (typeof parsed.should_apply !== 'boolean') errors.push('should_apply must be a boolean');
  if (typeof parsed.reason !== 'string' || parsed.reason.length > 300) errors.push('reason must be a string of at most 300 characters');
  if (!Array.isArray(parsed.missing_skills) || parsed.missing_skills.length > 5 || !parsed.missing_skills.every(s => typeof s === 'string')) errors.push('missing_skills must be an array of at most 5 strings');
  if (parsed.deadline !== null && parsed.deadline !== undefined && typeof parsed.deadline !== 'string') errors.push('deadline must be a string or null');
  if (parsed.eligibility !== null && parsed.eligibility !== undefined && typeof parsed.eligibility !== 'string') errors.push('eligibility must be a string or null');
  if (parsed.ctc_or_stipend !== null && parsed.ctc_or_stipend !== undefined && typeof parsed.ctc_or_stipend !== 'string') errors.push('ctc_or_stipend must be a string or null');
  if (errors.length) return { ok: false, error: errors.join('; ') };
  return { ok: true, parsed };
}

const resp = $json;
const ctx = $('Check Cache').all()[$itemIndex].json;
const content = resp.content || [];
const textBlock = content.find(b => b.type === 'text');
const rawText = textBlock ? textBlock.text : '';
const usage = resp.usage || {};

const result = tryValidate(rawText);

return {
  json: {
    content_hash: ctx.content_hash,
    prompt_version: ctx.prompt_version,
    model: ctx.model,
    posting_id: ctx.posting_id,
    company: ctx.company,
    role: ctx.role,
    location: ctx.location,
    employment_type: ctx.employment_type,
    apply_url: ctx.apply_url,
    source: ctx.source,
    notify_min_score: ctx.notify_min_score,
    system_message: ctx.system_message,
    user_message: ctx.user_message,
    valid: result.ok,
    match_score: result.ok ? result.parsed.match_score : null,
    should_apply: result.ok ? result.parsed.should_apply : null,
    reason: result.ok ? result.parsed.reason : null,
    missing_skills: result.ok ? result.parsed.missing_skills : null,
    deadline: result.ok ? (result.parsed.deadline || null) : null,
    eligibility: result.ok ? (result.parsed.eligibility || null) : null,
    ctc_or_stipend: result.ok ? (result.parsed.ctc_or_stipend || null) : null,
    input_tokens: usage.input_tokens || 0,
    output_tokens: usage.output_tokens || 0,
    retry_user_message: result.ok ? null : (ctx.user_message + '\n\nYour previous response was invalid and could not be used: ' + result.error + '\nRespond again with STRICT JSON ONLY, matching exactly the required shape, no other text, no markdown fences.')
  }
};

function tryValidate(rawText) {
  let parsed;
  try {
    const cleaned = (rawText || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
    parsed = JSON.parse(cleaned);
  } catch (e) {
    return { ok: false, error: 'JSON parse error: ' + e.message };
  }
  const errors = [];
  if (!Number.isInteger(parsed.match_score) || parsed.match_score < 0 || parsed.match_score > 100) errors.push('match_score must be an integer 0-100');
  if (typeof parsed.should_apply !== 'boolean') errors.push('should_apply must be a boolean');
  if (typeof parsed.reason !== 'string' || parsed.reason.length > 300) errors.push('reason must be a string of at most 300 characters');
  if (!Array.isArray(parsed.missing_skills) || parsed.missing_skills.length > 5 || !parsed.missing_skills.every(s => typeof s === 'string')) errors.push('missing_skills must be an array of at most 5 strings');
  if (parsed.deadline !== null && parsed.deadline !== undefined && typeof parsed.deadline !== 'string') errors.push('deadline must be a string or null');
  if (parsed.eligibility !== null && parsed.eligibility !== undefined && typeof parsed.eligibility !== 'string') errors.push('eligibility must be a string or null');
  if (parsed.ctc_or_stipend !== null && parsed.ctc_or_stipend !== undefined && typeof parsed.ctc_or_stipend !== 'string') errors.push('ctc_or_stipend must be a string or null');
  if (errors.length) return { ok: false, error: errors.join('; ') };
  return { ok: true, parsed };
}

const resp = $json;
const ctx = $('Validate Attempt 1').all()[$itemIndex].json;
const content = resp.content || [];
const textBlock = content.find(b => b.type === 'text');
const rawText = textBlock ? textBlock.text : '';
const usage = resp.usage || {};

const result = tryValidate(rawText);

const totalInputTokens = (ctx.input_tokens || 0) + (usage.input_tokens || 0);
const totalOutputTokens = (ctx.output_tokens || 0) + (usage.output_tokens || 0);
const costUsd = totalInputTokens / 1e6 * 1.00 + totalOutputTokens / 1e6 * 5.00;

return {
  json: {
    content_hash: ctx.content_hash,
    prompt_version: ctx.prompt_version,
    model: ctx.model,
    posting_id: ctx.posting_id,
    company: ctx.company,
    role: ctx.role,
    location: ctx.location,
    employment_type: ctx.employment_type,
    apply_url: ctx.apply_url,
    source: ctx.source,
    notify_min_score: ctx.notify_min_score,
    match_score: result.ok ? result.parsed.match_score : null,
    should_apply: result.ok ? result.parsed.should_apply : false,
    reason: result.ok ? result.parsed.reason : ('Invalid LLM output after retry: ' + result.error).slice(0, 300),
    missing_skills: JSON.stringify(result.ok ? result.parsed.missing_skills : []),
    deadline: result.ok ? (result.parsed.deadline || null) : null,
    eligibility: result.ok ? (result.parsed.eligibility || null) : null,
    ctc_or_stipend: result.ok ? (result.parsed.ctc_or_stipend || null) : null,
    input_tokens: totalInputTokens,
    output_tokens: totalOutputTokens,
    cost_usd: Math.round(costUsd * 1e6) / 1e6,
    invalid: !result.ok,
    cache_hit: false
  }
};

const persisted = $json;
const ctx = $('Merge For Persist').all()[$itemIndex].json;

const threshold = (ctx.notify_min_score !== undefined && ctx.notify_min_score !== null) ? ctx.notify_min_score : 75;
const shouldNotify = !persisted.invalid && persisted.should_apply === true && typeof persisted.match_score === 'number' && persisted.match_score >= threshold;

return {
  json: {
    posting_id: ctx.posting_id,
    company: ctx.company,
    role: ctx.role,
    location: ctx.location,
    employment_type: ctx.employment_type,
    apply_url: ctx.apply_url,
    match_score: persisted.match_score,
    reason: persisted.reason,
    missing_skills: persisted.missing_skills,
    deadline: persisted.deadline,
    eligibility: persisted.eligibility,
    ctc_or_stipend: persisted.ctc_or_stipend,
    invalid: persisted.invalid,
    cache_hit: ctx.cache_hit,
    input_tokens: ctx.input_tokens,
    output_tokens: ctx.output_tokens,
    cost_usd: ctx.cost_usd,
    should_notify: shouldNotify
  }
};

const total = $('Hash Prompt Version').all().length;
const persistedItems = $('Merge For Persist').all();
const prefiltered = total - persistedItems.length;

let cacheHits = 0;
try { cacheHits = $('Use Cached Evaluation').all().length; } catch (e) { cacheHits = 0; }

let llmCalls = 0;
try { llmCalls = $('Score Posting').all().length; } catch (e) { llmCalls = 0; }

let notified = 0;
try { notified = $('Call WF-3').all().length; } catch (e) { notified = 0; }

const costUsd = persistedItems.reduce((sum, i) => sum + (i.json.cost_usd || 0), 0);

return [{
  json: {
    total,
    prefiltered,
    cache_hits: cacheHits,
    llm_calls: llmCalls,
    notified,
    cost_usd: Math.round(costUsd * 1e6) / 1e6
  }
}];
